"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

/*
 * Base UI splits Radix's checked="indeterminate" into a separate boolean
 * `indeterminate` prop; the Root renders a <span>, so disabled styling
 * hangs off data-disabled instead of the :disabled pseudo-class.
 */

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Checkbox = React.forwardRef<
  HTMLSpanElement,
  WithClassName<CheckboxPrimitive.Root.Props>
>(({ className, indeterminate, ...props }, ref) => (
  <CheckboxPrimitive.Root
    data-slot="checkbox"
    ref={ref}
    indeterminate={indeterminate}
    className={cn(
      "peer inline-flex items-center justify-center h-[1.125rem] w-[1.125rem] shrink-0 rounded-sm",
      "bg-input [box-shadow:var(--shadow-inset)]",
      "transition-[background,box-shadow] duration-fast",
      "focus-visible:outline-none focus-visible:[box-shadow:var(--shadow-inset),0_0_0_0.125rem_var(--ring)]",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      "data-checked:bg-[image:var(--pill-gradient)] data-checked:text-foreground data-checked:[box-shadow:var(--shadow-pill)]",
      "data-indeterminate:bg-[image:var(--pill-gradient)] data-indeterminate:text-foreground data-indeterminate:[box-shadow:var(--shadow-pill)]",
      className
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
      {indeterminate ? (
        <Icon icon="tabler:minus" className="h-3 w-3" />
      ) : (
        <Icon icon="tabler:check" className="h-3 w-3" />
      )}
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
))
Checkbox.displayName = "Checkbox"

export { Checkbox }
